// Exhaust row multisets, allowing repeated rows. Emit every completion, not just one.
use std::{collections::HashMap,io::{self,BufRead}};
type A=[u32;26];const F:u32=(1<<26)-1;
fn alpha(a:&A,m:u32,c:&mut HashMap<u32,u8>)->u8{if m==0{return 0}if let Some(&n)=c.get(&m){return n}let i=m.trailing_zeros()as usize;let r=m&(m-1);let n=alpha(a,r,c).max(1+alpha(a,r&!a[i],c));c.insert(m,n);n}
fn visit(a:&A,rows:&[u32],compat:&[Vec<u64>],mut opts:Vec<u64>,sub:&[(u32,u8)],c:&mut HashMap<u32,u8>,p:&mut Vec<u32>,d:[u8;26],id:usize){let left=8-p.len();for w in 0..opts.len(){while opts[w]!=0{let t=opts[w].trailing_zeros();let i=w*64+t as usize;let s=rows[i];let mut deg=d;for j in 0..26{deg[j]+=(s>>j&1)as u8}if deg.iter().all(|&v|v<=8 && v as usize+left-1>=7){let mut next=sub.to_vec();let mut valid=true;for &(m,k)in sub{let u=m&!s;if u.count_ones()+k as u32+1>8 && alpha(a,u,c)+k+1>8{valid=false;break}next.push((u,k+1))}if valid{p.push(s);if left==1{println!("{} {:?}",id,p)}else{let v=opts.iter().zip(&compat[i]).map(|(x,y)|x&y).collect();visit(a,rows,compat,v,&next,c,p,deg,id)}p.pop();}}opts[w]&=!(1<<t);}}}
fn main(){for(id,l)in io::stdin().lock().lines().enumerate(){let a:A=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect::<Vec<_>>().try_into().unwrap();let mut ss=vec![0u32];for i in 0..26{for j in 0..ss.len(){if ss[j]&a[i]==0{ss.push(ss[j]|1<<i)}}}let rows:Vec<_>=ss.into_iter().filter(|s|(6..=7).contains(&s.count_ones())).collect();let n=rows.len();let w=(n+63)/64;let mut cp=vec![vec![0u64;w];n];let mut c=HashMap::new();for(i,&s)in rows.iter().enumerate(){for(j,&t)in rows.iter().enumerate().skip(i){if alpha(&a,F&!(s|t),&mut c)<=6{cp[i][j/64]|=1<<(j%64)}}}let mut opts=vec![u64::MAX;w];if n%64!=0{opts[w-1]=(1u64<<(n%64))-1}visit(&a,&rows,&cp,opts,&[(F,0)],&mut c,&mut vec![],a.map(|v|v.count_ones()as u8),id);println!("done {}",id)}}
